static API_ElemTypeID Type(const GS::UniString& n) {
 if(n=="Wall")return API_WallID;if(n=="Slab")return API_SlabID;if(n=="Roof")return API_RoofID;if(n=="Shell")return API_ShellID;if(n=="Zone")return API_ZoneID;if(n=="Beam")return API_BeamID;if(n=="Column")return API_ColumnID;if(n=="CurtainWall")return API_CurtainWallID;if(n=="Stair")return API_StairID;if(n=="Railing")return API_RailingID;if(n=="Opening")return API_OpeningID;if(n=="Object")return API_ObjectID;return API_ZombieElemID;
}
GS::ObjectState GetNativeElementDefaultsV1Command::Execute(const GS::ObjectState& p,GS::ProcessControl&) const {
 GS::Array<GS::UniString> types;p.Get("types",types);GS::ObjectState out("nativeModelWrites",0,"geometryAuthority","TOOL_DEFAULTS_NOT_PLACED_GEOMETRY");const auto& list=out.AddList<GS::ObjectState>("defaults");
 for(const auto& n:types){API_Element e={};e.header.type.typeID=Type(n);if(e.header.type.typeID==API_ZombieElemID){list(CreateErrorResponse(APIERR_BADPARS,"Unsupported tool"));continue;}auto err=ACAPI_Element_GetDefaults(&e,nullptr);if(err!=NoError){list(CreateErrorResponse(err,"GetDefaults"));continue;}GS::ObjectState row("type",n,"nativeTypeId",static_cast<Int32>(e.header.type.typeID),"variationId",static_cast<Int32>(e.header.type.variationID),"homeStory",static_cast<Int32>(e.header.floorInd),"layerIndex",e.header.layer.ToInt32_Deprecated());
 if(n=="Wall"){row.Add("height",e.wall.height);row.Add("thickness",e.wall.thickness);row.Add("buildingMaterialIndex",e.wall.buildingMaterial.ToInt32_Deprecated());}
 else if(n=="Slab"){row.Add("thickness",e.slab.thickness);row.Add("buildingMaterialIndex",e.slab.buildingMaterial.ToInt32_Deprecated());}
 else if(n=="Roof"){row.Add("roofClass",static_cast<Int32>(e.roof.roofClass));row.Add("thickness",e.roof.shellBase.thickness);row.Add("buildingMaterialIndex",e.roof.shellBase.buildingMaterial.ToInt32_Deprecated());}
 else if(n=="Shell"){row.Add("shellClass",static_cast<Int32>(e.shell.shellClass));row.Add("thickness",e.shell.shellBase.thickness);row.Add("buildingMaterialIndex",e.shell.shellBase.buildingMaterial.ToInt32_Deprecated());}
 else row.Add("complexParameters","NOT_SERIALIZED_HEADER_DEFAULTS_ONLY");list(row);}return out;
}
GS::ObjectState GetNativePolygonMemoV1Command::Execute(const GS::ObjectState& p,GS::ProcessControl&) const {
 GS::Array<GS::ObjectState> elements;p.Get("elements",elements);GS::ObjectState out("nativeModelWrites",0,"geometryAuthority","NATIVE_POLYGON_MEMO_NOT_RESULTANT_BREP");const auto& list=out.AddList<GS::ObjectState>("elements");
 for(const auto& item:elements){const auto* id=item.Get("elementId");if(!id){list(CreateErrorResponse(APIERR_BADPARS,"elementId required"));continue;}API_Element e={};e.header.guid=GetGuidFromObjectState(*id);auto err=ACAPI_Element_Get(&e);if(err!=NoError){list(CreateErrorResponse(err,"GetElement"));continue;}API_ElementMemo memo={};err=ACAPI_Element_GetMemo(e.header.guid,&memo,APIMemoMask_Polygon);const GS::OnExit cleanup([&](){ACAPI_DisposeElemMemoHdls(&memo);});if(err!=NoError){list(CreateErrorResponse(err,"GetMemo Polygon"));continue;}GS::ObjectState row("elementId",CreateGuidObjectState(e.header.guid),"nativeTypeId",static_cast<Int32>(e.header.type.typeID),"variationId",static_cast<Int32>(e.header.type.variationID),"homeStory",static_cast<Int32>(e.header.floorInd));
 const auto& coords=row.AddList<GS::ObjectState>("coordinates");const GSSize nc=memo.coords?BMGetHandleSize(reinterpret_cast<GSHandle>(memo.coords))/sizeof(API_Coord):0;
 for(GSIndex i=1;i<nc;++i)coords(GS::ObjectState("index",static_cast<Int32>(i),"x",(*memo.coords)[i].x,"y",(*memo.coords)[i].y));
 const auto& ends=row.AddList<Int32>("contourEnds");const GSSize ne=memo.pends?BMGetHandleSize(reinterpret_cast<GSHandle>(memo.pends))/sizeof(Int32):0;for(GSIndex i=1;i<ne;++i)ends((*memo.pends)[i]);
 const auto& arcs=row.AddList<GS::ObjectState>("arcs");const GSSize na=memo.parcs?BMGetHandleSize(reinterpret_cast<GSHandle>(memo.parcs))/sizeof(API_PolyArc):0;for(GSIndex i=0;i<na;++i)arcs(GS::ObjectState("beginIndex",(*memo.parcs)[i].begIndex,"endIndex",(*memo.parcs)[i].endIndex,"angle",(*memo.parcs)[i].arcAngle));list(row);}return out;
}
GS::ObjectState GetNativeWorkingUnitsV1Command::Execute(const GS::ObjectState&,GS::ProcessControl&) const {
 API_WorkingUnitPrefs prefs={};auto err=ACAPI_ProjectSetting_GetPreferences(&prefs,APIPrefs_WorkingUnitsID);if(err!=NoError)return CreateErrorResponse(err,"Get WorkingUnits preferences");return GS::ObjectState("nativeModelWrites",0,"lengthUnit",static_cast<Int32>(prefs.lengthUnit),"areaUnit",static_cast<Int32>(prefs.areaUnit),"volumeUnit",static_cast<Int32>(prefs.volumeUnit),"angleUnit",static_cast<Int32>(prefs.angleUnit),"lengthDecimals",prefs.lenDecimals,"areaDecimals",prefs.areaDecimals,"volumeDecimals",prefs.volumeDecimals,"angleDecimals",prefs.angleDecimals);
}
GS::ObjectState GetNativeGroupRootsV1Command::Execute(const GS::ObjectState& p,GS::ProcessControl&) const {
 GS::Array<GS::ObjectState> elements;p.Get("elements",elements);GS::ObjectState out("nativeModelWrites",0);const auto& list=out.AddList<GS::ObjectState>("groups");for(const auto& item:elements){const auto* id=item.Get("elementId");if(!id){list(CreateErrorResponse(APIERR_BADPARS,"elementId required"));continue;}API_Guid guid=GetGuidFromObjectState(*id),immediate=APINULLGuid,root=APINULLGuid;auto err=ACAPI_Grouping_GetGroup(guid,&immediate);if(err!=NoError){list(CreateErrorResponse(err,"GetGroup"));continue;}GS::ObjectState row("elementId",CreateGuidObjectState(guid),"groupId",CreateGuidObjectState(immediate));if(immediate!=APINULLGuid){err=ACAPI_Grouping_GetRootGroup(guid,&root);if(err!=NoError){list(CreateErrorResponse(err,"GetRootGroup"));continue;}}row.Add("rootGroupId",CreateGuidObjectState(root));list(row);}return out;
}
GS::ObjectState GetNativeLibraryPartOriginV1Command::Execute(const GS::ObjectState& p,GS::ProcessControl&) const {
 auto manager=ACAPI::Library::GetLibraryManager();if(manager.IsErr())return CreateErrorResponse(manager.UnwrapErr().kind,"GetLibraryManager");GS::Array<Int32> indices;p.Get("indices",indices);GS::ObjectState out("nativeModelWrites",0);const auto& list=out.AddList<GS::ObjectState>("parts");for(auto index:indices){auto part=manager->GetLibPartByLibInd(index);if(part.IsErr()){list(CreateErrorResponse(part.UnwrapErr().kind,"GetLibPartByLibInd"));continue;}GS::ObjectState row("index",index);auto name=part->GetName();if(name.IsOk())row.Add("name",*name);auto library=manager->GetLibraryOfLibPart(*part);if(library.IsOk()){auto label=library->GetName();if(label.IsOk())row.Add("libraryName",*label);}else row.Add("originStatus","LIBRARY_ORIGIN_UNAVAILABLE");list(row);}return out;
}
